export function lengthOfLongestSubstring(s: string): number {
  const lastSeen = new Map<string, number>(); // char -> last index
  let left = 0;
  let best = 0;

  for (let right = 0; right < s.length; right++) {
    const ch = s.charAt(right);
    const prev = lastSeen.get(ch);
    // Only move left forward. Without `prev >= left`,
    // "abba" moves left back to 1 and returns 3.
    if (prev !== undefined && prev >= left) left = prev + 1;
    lastSeen.set(ch, right);
    best = Math.max(best, right - left + 1);
  }
  return best; // O(n) time, O(k) memory for k distinct chars
}

// Test out loud, edge cases first
console.assert(lengthOfLongestSubstring("") === 0);
console.assert(lengthOfLongestSubstring("bbbbb") === 1);
console.assert(lengthOfLongestSubstring("abcabcbb") === 3);
console.assert(lengthOfLongestSubstring("abba") === 2);

function twoSum(nums: number[], target: number): [number, number] | null {
  const seen = new Map<number, number>(); // value -> index
  for (let i = 0; i < nums.length; i++) {
    seen.set(nums[i], i);
    const j = seen.get(target - nums[i]);
    if (j !== undefined) return [j, i];
  }
  return null;
}

// assumes ok(0) === true and ok is monotonic
function lastTrue(n: number, ok: (x: number) => boolean): number {
  let lo = 0;
  let hi = n;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (ok(mid)) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

app.post("/bookings", async (req, res) => {
  const { roomId, date } = req.body;
  const existing = await db.booking.findFirst({
    where: { roomId, date },
  });
  if (existing) {
    return res.status(409).json({ error: "Room already booked" });
  }
  const booking = await db.booking.create({ data: { roomId, date } });
  res.status(201).json(booking);
});

